import type { FsEntry } from 'x-coder'

import { distinct } from './distinct'
import { VCS_MARKERS } from './vcs-markers'

/**
 * The row's `vcs`: the version-control systems whose marker is in the
 * session's directory, Perforce too when P4PORT is set, comma-joined.
 *
 * @param list lists a directory
 * @param cwd the session's directory
 * @param hasP4Port whether P4PORT is set
 * @returns the systems found, or undefined for none or an unlistable directory
 */
export async function vcsOf(
  list: (path: string) => Promise<readonly FsEntry[]>,
  cwd: string,
  hasP4Port: boolean,
): Promise<string | undefined> {
  let entries: readonly FsEntry[]

  try {
    entries = await list(cwd)
  } catch {
    entries = []
  }

  const names = new Set(entries.map(entry => entry.name))

  const found = distinct([
    ...(hasP4Port ? ['perforce'] : []),
    ...VCS_MARKERS.flatMap(([marker, system]) =>
      names.has(marker) ? [system] : [],
    ),
  ])

  return found.length > 0 ? found.join(',') : undefined
}

files.hooks/context/version-of/version-of.ts:
/**
 * A version string reduced to what a row may carry, as the CLI reduces the
 * Agent SDK's: its semver core, `unknown` as said, else `other`.
 *
 * @param version the variable as read; undefined stays undefined
 * @returns the version for the row, or undefined
 */
export function versionOf(version: string | undefined) {
  const isKept = version === undefined || version === 'unknown'
  const core = /^\d{1,8}\.\d{1,8}\.\d{1,8}(?!\d)/.exec(version ?? '')?.[0]

  return isKept ? version : (core ?? 'other')
}

files.hooks/context/wsl-version-of/wsl-version:
/**
 * The WSL release a Linux kernel string names, as the CLI reads
 * `/proc/version`: the digit after `WSL`, `1` for the `Microsoft` kernels.
 *
 * @param readProcVersion reads `/proc/version` as text
 * @returns the WSL version, or undefined off WSL or when the file is unread
 */
export async function wslVersionOf(
  readProcVersion: () => Promise<string>,
): Promise<string | undefined> {
  let kernel: string

  try {
    kernel = (await readProcVersion()).toLowerCase()
  } catch {
    return undefined
  }

  const isMicrosoft = kernel.includes('microsoft')

  return /wsl(\d+)/.exec(kernel)?.[1] ?? (isMicrosoft ? '1' : undefined)
}

